query get($id: bigint!) {
  clipart_categories_by_pk(id: $id) {
    v
    cliparts(where: {deleted_at: {_is_null: true}}, order_by: {position: asc}) {
      id
      position
      thumbnail
      url
      color
      name
      created_at
      __typename
    }
    __typename
  }
}
